#!/usr/bin/env python3import sysfrom pathlib import Pathp = Path("bin/agent/prompts.py")content = p.read_text(encoding="utf-8")# Check if the collapsed line existsif 'def _serialize_element(elem: ET.Element, indent: str = "") -> str:    """' in content:    print("Found collapsed line, fixing...")        # Split by the collapsed line and the end marker    parts = content.split('def _serialize_element(elem: ET.Element, indent: str = "") -> str:', 1)    if len(parts) != 2:        print("ERROR: could not split")        sys.exit(1)        before = parts[0]    rest = parts[1]        # Find where _read_tree starts in rest    read_tree_idx = rest.find('def _read_tree(path: Path) -> ET.ElementTree:')    if read_tree_idx == -1:        print("ERROR: could not find _read_tree")        sys.exit(1)        # Build the new functions    new_funcs = '''def _serialize_element(elem: ET.Element, indent: str = "") -> str:    """Serialize an Element to XML string with CDATA for value elements."""    parts: list[str] = []    tag = elem.tag    attrs = ""    for k, v in elem.attrib.items():        attrs += f' {k}="{v}"'    children = list(elem)    has_children = len(children) > 0    if tag == "value" and elem.text:        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>")        return "".join(parts)    if not has_children and (elem.text is None or not elem.text.strip()):        parts.append(f"{indent}<{tag}{attrs} />")    elif not has_children:        parts.append(f"{indent}<{tag}{attrs}>{elem.text or ''}</{tag}>")    else:        parts.append(f"{indent}<{tag}{attrs}>")        for child in children:            parts.append("\\n")            parts.append(_serialize_element(child, indent + "  "))        parts.append(f"\\n{indent}</{tag}>")    return "".join(parts)def _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:    """Write the prompts XML tree to target using CDATA for value elements."""    root = tree.getroot()    xml_str = '<?xml version="1.0" encoding="UTF-8"?>\\n'    xml_str += _serialize_element(root)    xml_str += "\\n"    target.write_text(xml_str, encoding="utf-8")'''        new_content = before + new_funcs + rest[read_tree_idx:]    p.write_text(new_content, encoding="utf-8")        # Verify    verify = p.read_text(encoding="utf-8")    if 'def _serialize_element(elem: ET.Element, indent: str = "") -> str:\n' in verify:        print("VERIFIED: fix applied successfully")    else:        print("ERROR: fix did not apply")        sys.exit(1)else:    print("Collapsed line not found - may already be fixed")    # Check if it's already properly formatted    if 'def _serialize_element(elem: ET.Element, indent: str = "") -> str:\n' in content:        print("Already properly formatted")    else:        print("ERROR: unexpected state")        sys.exit(1)